const express = require('express');
const { Worker } = require('worker_threads');
const path = require('path');
const { authenticateJwt } = require('../middleware/auth');
const { db } = require('../db');

const router = express.Router();

router.post('/api/reports/tax-pdf/:reportId/generate', authenticateJwt, async (req, res) => {
  const report = await db.query(
    'SELECT id FROM tax_reports WHERE id = $1 AND user_id = $2',
    [req.params.reportId, req.user.id]
  );
  if (!report.rows.length) {
    return res.status(403).json({ error: 'Forbidden: you do not own this tax report' });
  }

  const worker = new Worker(path.resolve(__dirname, '../workers/taxPdfWorker.js'), {
    workerData: {
      reportId: req.params.reportId,
      requestedFormat: req.body.format || 'PDF/A',
    },
  });

  worker.on('message', (result) => {
    res.json({ success: true, downloadUrl: result.s3SignedUrl, checksum: result.sha256 });
  });

  worker.on('error', (err) => {
    res.status(500).json({ error: 'Worker thread execution failed' });
  });
});
